    return finish(launch(inp, cpu, wall))


def numbers(text, want, case):
    toks = text.split()
    if len(toks) != want:
        fail('case %d: expected %d output values, got %d' % (case, want, len(toks)))
    try:
        return [float(t) for t in toks]
    except ValueError:
        fail('case %d: unparseable output value' % case)

def nb_sim(bodies, dt, steps):
    n = len(bodies)
    ms = [b[0] for b in bodies]
    x = [b[1] for b in bodies]; y = [b[2] for b in bodies]
    vx = [b[3] for b in bodies]; vy = [b[4] for b in bodies]

    def acc():
        ax = [0.0] * n; ay = [0.0] * n; mn = 1e300
        for i in range(n):
            xi = x[i]; yi = y[i]; sx = 0.0; sy = 0.0
            for j in range(n):
                if j == i:
                    continue
                dx = x[j] - xi; dy = y[j] - yi
                r2 = dx * dx + dy * dy
                if r2 < mn:
                    mn = r2
                f = ms[j] / (r2 * math.sqrt(r2))
                sx += f * dx; sy += f * dy
            ax[i] = sx; ay[i] = sy
        return ax, ay, mn

    ax, ay, minr2 = acc()
    h = 0.5 * dt * dt
    for _ in range(steps):
        for i in range(n):
            x[i] += vx[i] * dt + h * ax[i]
            y[i] += vy[i] * dt + h * ay[i]
        bx, by, mn = acc()
        if mn < minr2:
            minr2 = mn
        for i in range(n):
            vx[i] += 0.5 * (ax[i] + bx[i]) * dt
            vy[i] += 0.5 * (ay[i] + by[i]) * dt
        ax, ay = bx, by
    out = []
    for i in range(n):
        out += [x[i], y[i], vx[i], vy[i]]
    return out, minr2

rng = random.Random(0x0B0D1E5)
cases = [([(1.0, -1.0, 0.0, 0.0, -0.5), (1.0, 1.0, 0.0, 0.0, 0.5)], 0.01, 100),
         ([(1.7, 0.25, -0.5, 0.3, -0.2)], 0.01, 120)]
q = lambda a, b: float('%.4f' % rng.uniform(a, b))
while len(cases) < 24:
    n = rng.randint(2, 6)
    bodies = []
    while len(bodies) < n:
        px, py = q(-4, 4), q(-4, 4)
        if all((px - b[1]) ** 2 + (py - b[2]) ** 2 >= 1.44 for b in bodies):
            bodies.append((q(0.3, 2.0), px, py, q(-0.6, 0.6), q(-0.6, 0.6)))
    dt = rng.choice([0.002, 0.005, 0.01])
    steps = rng.randint(50, 300)
    res, mr2 = nb_sim(bodies, dt, steps)
    if mr2 < 0.09 or max(abs(v) for v in res) > 50:
        continue
    nudged = [(bodies[0][0], bodies[0][1] + 1e-9) + bodies[0][2:]] + bodies[1:]
    res2, _ = nb_sim(nudged, dt, steps)
    if max(abs(a - b) for a, b in zip(res, res2)) > 1e-6:
        continue
    cases.append((bodies, dt, steps))
inp = ['%d' % len(cases)]
for bodies, dt, steps in cases:
    inp.append('%d %g %d' % (len(bodies), dt, steps))
    inp += [' '.join('%.4f' % v for v in b) for b in bodies]
inp = '\n'.join(inp) + '\n'
start_build()
want = [nb_sim(b, dt, s)[0] for b, dt, s in cases]
finish_build()
got = numbers(run(inp, 10, 20), sum(len(w) for w in want), 0)
k = 0
for i, w in enumerate(want):
    for v in w:
        if not abs(got[k] - v) <= 1e-5:
            fail('mismatch at case %d' % i)
        k += 1
print('OK: %d hidden cases' % len(cases))

